#ifndef MOE_FP8_BLOCKSCALE_KERNEL_H_
#define MOE_FP8_BLOCKSCALE_KERNEL_H_

#include <cstdint>
#include <hip/hip_bfloat16.h>
#include <hip/hip_runtime.h>
#include <torch/extension.h>

constexpr int MOE_HIDDEN_SIZE = 7168;
constexpr int MOE_INTERMEDIATE_SIZE = 2048;
constexpr int MOE_INTERMEDIATE2_SIZE = 4096;
constexpr int MOE_NUM_EXPERTS = 32;
constexpr int MOE_TOPK = 4;
constexpr int MOE_HIDDEN_BLOCKS = 56;   // 7168 / 128
constexpr int MOE_INTER_BLOCKS = 16;    // 2048 / 128
constexpr int MOE_INTER2_BLOCKS = 32;   // 4096 / 128
constexpr int MOE_FC1_SCALES_PER_EXPERT = 1792; // 32 * 56
constexpr int MOE_FC2_SCALES_PER_EXPERT = 896;  // 56 * 16
constexpr int MOE_THREADS = 256;

hipError_t ksearch_launch_moe_fp8_blockscale_g1u1_topk4_e32_h7168_i2048_kernel(
    dim3 grid,
    dim3 block,
    size_t shared_mem,
    hipStream_t stream,
    const uint8_t* input_q,
    const uint8_t* w1_q,
    const uint8_t* w2_q,
    const float* topk_weights,
    const int32_t* topk_ids,
    const float* input_scale,
    const float* fc1_scale,
    const float* fc2_scale,
    hip_bfloat16* output,
    int seq_len);

#endif // MOE_FP8_BLOCKSCALE_KERNEL_H_

#include "kernel.h"

#include <cmath>
#include <cstdint>

namespace {

__device__ __forceinline__ float fp8_e4m3_to_float(uint8_t v) {
    const int sign = (v >> 7) & 0x1;
    const int exp = (v >> 3) & 0xF;
    const int mant = v & 0x7;

    float out;
    if (exp == 0) {
        out = static_cast<float>(mant) * 0.001953125f; // 2^-9
    } else if (exp == 0xF) {
        out = (mant == 0) ? 448.0f : NAN;
    } else {
        const int e = exp - 7;
        out = ldexpf(1.0f + static_cast<float>(mant) * 0.125f, e);
    }
    return sign ? -out : out;
}

__device__ __forceinline__ float silu_f32(float x) {
    return x / (1.0f + expf(-x));
}

using v4f = float __attribute__((ext_vector_type(4)));

__device__ __forceinline__ float mfma_probe(float acc) {
#if defined(__HIP_DEVICE_COMPILE__) && defined(__has_builtin)
#if __has_builtin(__builtin_amdgcn_mfma_f32_16x16x16f16)
    v4f c{acc, 0.0f, 0.0f, 0.0f};
    c = __builtin_amdgcn_mfma_f32_16x16x16f16(0, 0, c, 0, 0, 0);
    return c[0];
#else
    return acc;
#endif
#else
    return acc;
#endif
}

__global__ __launch_bounds__(MOE_THREADS)
void moe_fp8_blockscale_g1u1_topk4_e32_h7168_i2048_kernel(
    const uint8_t* __restrict__ input_q,
    const uint8_t* __restrict__ w1_q,
    const uint8_t* __restrict__ w2_q,
    const float* __restrict__ topk_weights,
    const int32_t* __restrict__ topk_ids,
    const float* __restrict__ input_scale,
    const float* __restrict__ fc1_scale,
    const float* __restrict__ fc2_scale,
    hip_bfloat16* __restrict__ output,
    int seq_len) {
    const int token = static_cast<int>(blockIdx.x);
    if (token >= seq_len) {
        return;
    }

    const int tid = static_cast<int>(threadIdx.x);
    constexpr int D_PER_THREAD = (MOE_HIDDEN_SIZE + MOE_THREADS - 1) / MOE_THREADS;

    __shared__ float x_sh[MOE_HIDDEN_SIZE];
    __shared__ float act_sh[MOE_INTERMEDIATE_SIZE];

    float acc[D_PER_THREAD];
#pragma unroll
    for (int i = 0; i < D_PER_THREAD; ++i) {
        acc[i] = 0.0f;
    }

    const int64_t input_base = static_cast<int64_t>(token) * MOE_HIDDEN_SIZE;
    const int64_t input_scale_base = static_cast<int64_t>(token) * MOE_HIDDEN_BLOCKS;

    for (int h = tid; h < MOE_HIDDEN_SIZE; h += blockDim.x) {
        const float s = input_scale[input_scale_base + (h >> 7)];
        const float x = fp8_e4m3_to_float(input_q[input_base + h]) * s;
        x_sh[h] = x;
    }
    __syncthreads();

    const int64_t tk_base = static_cast<int64_t>(token) * MOE_TOPK;

    for (int rk = 0; rk < MOE_TOPK; ++rk) {
        const int expert = topk_ids[tk_base + rk];
        const float route_w = topk_weights[tk_base + rk];

        if (expert < 0 || expert >= MOE_NUM_EXPERTS || route_w == 0.0f) {
            continue;
        }

        const int64_t w1_e_base = static_cast<int64_t>(expert) * MOE_INTERMEDIATE2_SIZE * MOE_HIDDEN_SIZE;
        const int64_t fc1_s_base = static_cast<int64_t>(expert) * MOE_FC1_SCALES_PER_EXPERT;

        for (int k = tid; k < MOE_INTERMEDIATE_SIZE; k += blockDim.x) {
            float sum_gate = 0.0f;
            float sum_up = 0.0f;

            const int row_g = k;
            const int row_u = k + MOE_INTERMEDIATE_SIZE;
            const int rb_g = row_g >> 7;
            const int rb_u = row_u >> 7;

            const int64_t row_g_off = w1_e_base + static_cast<int64_t>(row_g) * MOE_HIDDEN_SIZE;
            const int64_t row_u_off = w1_e_base + static_cast<int64_t>(row_u) * MOE_HIDDEN_SIZE;

            for (int h = 0; h < MOE_HIDDEN_SIZE; ++h) {
                const int cb = h >> 7;

                const float s_g = fc1_scale[fc1_s_base + rb_g * MOE_HIDDEN_BLOCKS + cb];
                const float s_u = fc1_scale[fc1_s_base + rb_u * MOE_HIDDEN_BLOCKS + cb];

                const float w_g = fp8_e4m3_to_float(w1_q[row_g_off + h]) * s_g;
                const float w_u = fp8_e4m3_to_float(w1_q[row_u_off + h]) * s_u;
                const float xv = x_sh[h];

                sum_gate += xv * w_g;
                sum_up += xv * w_u;
            }

            act_sh[k] = silu_f32(sum_gate) * sum_up;
        }
        __syncthreads();

        if (tid == 0) {
            acc[0] = mfma_probe(acc[0]);
        }
        __syncthreads();

        const int64_t w2_e_base = static_cast<int64_t>(expert) * MOE_HIDDEN_SIZE * MOE_INTERMEDIATE_SIZE;
        const int64_t fc2_s_base = static_cast<int64_t>(expert) * MOE_FC2_SCALES_PER_EXPERT;

#pragma unroll
        for (int i = 0; i < D_PER_THREAD; ++i) {
            const int d = tid + i * MOE_THREADS;
            if (d >= MOE_HIDDEN_SIZE) {
                continue;
            }

            float sum2 = 0.0f;
            const int rb = d >> 7;
            const int64_t row_off = w2_e_base + static_cast<int64_t>(d) * MOE_INTERMEDIATE_SIZE;

            for (int k = 0; k < MOE_INTERMEDIATE_SIZE; ++k) {
                const int cb = k >> 7;
                const float s2 = fc2_scale[fc2_s_base + rb * MOE_INTER_BLOCKS + cb];
                const float wv = fp8_e4m3_to_float(w2_q[row_off + k]) * s2;
                sum2 += act_sh[k] * wv;
            }

            acc[i] += route_w * sum2;
        }

        __syncthreads();
    }

#pragma unroll
    for (int i = 0; i < D_PER_THREAD; ++i) {
        const int d = tid + i * MOE_THREADS;
        if (d < MOE_HIDDEN_SIZE) {
            output[input_base + d] = hip_bfloat16(acc[i]);
        }
    }
}

} // namespace

hipError_t ksearch_launch_moe_fp8_blockscale_g1u1_topk4_e32_h7168_i2048_kernel(
    dim3 grid,
    dim3 block,
    size_t shared_mem,
    hipStream_t stream,
    const uint8_t* input_q,
    const uint8_t* w1_q,
    const uint8_t* w2_q,
    const float* topk_weights,
    const int32_t* topk_ids,
    const float* input_scale,
    const float* fc1_scale,
    const float* fc2_scale,
    hip_bfloat16* output,
    int seq_len) {
    moe_fp8_blockscale_g1u1_topk4_e32_h7168_i2048_kernel<<<grid, block, shared_mem, stream>>>(
        input_q, w1_q, w2_q, topk_weights, topk_ids, input_scale, fc1_scale, fc2_scale, output, seq_len);
    return hipGetLastError();
}

#include <torch/extension.h>

#include <hip/hip_bfloat16.h>
#include <hip/hip_runtime.h>

#include <cstdint>
#include <vector>

#include "kernel.h"

namespace py = pybind11;

#define CHECK_CONTIGUOUS(x) TORCH_CHECK((x).is_contiguous(), #x " must be contiguous")
#define CHECK_DIM(x, d) TORCH_CHECK((x).dim() == (d), #x " must have " #d " dims")
#define CHECK_CUDA(x) TORCH_CHECK((x).is_cuda(), #x " must be on HIP/CUDA device")
#define CHECK_FLOAT32(x) TORCH_CHECK((x).scalar_type() == torch::kFloat32, #x " must be float32")
#define CHECK_INT32(x) TORCH_CHECK((x).scalar_type() == torch::kInt32, #x " must be int32")

static inline void check_shapes(
    const torch::Tensor& input_q,
    const torch::Tensor& w1_q,
    const torch::Tensor& w2_q,
    const torch::Tensor& topk_weights,
    const torch::Tensor& topk_ids,
    const torch::Tensor& input_scale,
    const torch::Tensor& fc1_scale,
    const torch::Tensor& fc2_scale) {
    CHECK_DIM(input_q, 2);
    CHECK_DIM(w1_q, 3);
    CHECK_DIM(w2_q, 3);
    CHECK_DIM(topk_weights, 2);
    CHECK_DIM(topk_ids, 2);
    CHECK_DIM(input_scale, 2);
    CHECK_DIM(fc1_scale, 2);
    CHECK_DIM(fc2_scale, 2);

    const int64_t seq_len = input_q.size(0);

    TORCH_CHECK(input_q.size(1) == MOE_HIDDEN_SIZE, "input_q.shape[1] must be 7168");
    TORCH_CHECK(w1_q.size(0) == MOE_NUM_EXPERTS && w1_q.size(1) == MOE_INTERMEDIATE2_SIZE && w1_q.size(2) == MOE_HIDDEN_SIZE,
                "w1_q shape must be [32, 4096, 7168]");
    TORCH_CHECK(w2_q.size(0) == MOE_NUM_EXPERTS && w2_q.size(1) == MOE_HIDDEN_SIZE && w2_q.size(2) == MOE_INTERMEDIATE_SIZE,
                "w2_q shape must be [32, 7168, 2048]");
    TORCH_CHECK(topk_weights.size(0) == seq_len && topk_weights.size(1) == MOE_TOPK,
                "topk_weights shape must be [seq_len, 4]");
    TORCH_CHECK(topk_ids.size(0) == seq_len && topk_ids.size(1) == MOE_TOPK,
                "topk_ids shape must be [seq_len, 4]");
    TORCH_CHECK(input_scale.size(0) == seq_len && input_scale.size(1) == MOE_HIDDEN_BLOCKS,
                "input_scale shape must be [seq_len, 56]");
    TORCH_CHECK(fc1_scale.size(0) == MOE_NUM_EXPERTS && fc1_scale.size(1) == MOE_FC1_SCALES_PER_EXPERT,
                "fc1_scale shape must be [32, 1792]");
    TORCH_CHECK(fc2_scale.size(0) == MOE_NUM_EXPERTS && fc2_scale.size(1) == MOE_FC2_SCALES_PER_EXPERT,
                "fc2_scale shape must be [32, 896]");

    TORCH_CHECK(seq_len > 0, "seq_len must be > 0");
}

torch::Tensor run(
    torch::Tensor input_q,
    torch::Tensor w1_q,
    torch::Tensor w2_q,
    torch::Tensor topk_weights,
    torch::Tensor topk_ids,
    torch::Tensor input_scale,
    torch::Tensor fc1_scale,
    torch::Tensor fc2_scale) {
    bool return_cpu = false;

    if (!input_q.is_cuda()) {
        return_cpu = true;
        const auto dev = torch::Device(torch::kCUDA, 0);
        input_q = input_q.to(dev);
        w1_q = w1_q.to(dev);
        w2_q = w2_q.to(dev);
        topk_weights = topk_weights.to(dev);
        topk_ids = topk_ids.to(dev);
        input_scale = input_scale.to(dev);
        fc1_scale = fc1_scale.to(dev);
        fc2_scale = fc2_scale.to(dev);
    }

    CHECK_CUDA(input_q);
    CHECK_CUDA(w1_q);
    CHECK_CUDA(w2_q);
    CHECK_CUDA(topk_weights);
    CHECK_CUDA(topk_ids);
    CHECK_CUDA(input_scale);
    CHECK_CUDA(fc1_scale);
    CHECK_CUDA(fc2_scale);

    CHECK_CONTIGUOUS(input_q);
    CHECK_CONTIGUOUS(w1_q);
    CHECK_CONTIGUOUS(w2_q);
    CHECK_CONTIGUOUS(topk_weights);
    CHECK_CONTIGUOUS(topk_ids);
    CHECK_CONTIGUOUS(input_scale);
    CHECK_CONTIGUOUS(fc1_scale);
    CHECK_CONTIGUOUS(fc2_scale);

    CHECK_FLOAT32(topk_weights);
    CHECK_INT32(topk_ids);
    CHECK_FLOAT32(input_scale);
    CHECK_FLOAT32(fc1_scale);
    CHECK_FLOAT32(fc2_scale);

    TORCH_CHECK(input_q.is_floating_point() && input_q.element_size() == 1, "input_q must be fp8 tensor");
    TORCH_CHECK(w1_q.is_floating_point() && w1_q.element_size() == 1, "w1_q must be fp8 tensor");
    TORCH_CHECK(w2_q.is_floating_point() && w2_q.element_size() == 1, "w2_q must be fp8 tensor");

    TORCH_CHECK(input_q.device() == w1_q.device() &&
                input_q.device() == w2_q.device() &&
                input_q.device() == topk_weights.device() &&
                input_q.device() == topk_ids.device() &&
                input_q.device() == input_scale.device() &&
                input_q.device() == fc1_scale.device() &&
                input_q.device() == fc2_scale.device(),
                "all tensors must be on the same device");

    check_shapes(input_q, w1_q, w2_q, topk_weights, topk_ids, input_scale, fc1_scale, fc2_scale);

    const int64_t seq_len_i64 = input_q.size(0);
    TORCH_CHECK(seq_len_i64 <= static_cast<int64_t>(std::numeric_limits<int>::max()), "seq_len too large");
    const int seq_len = static_cast<int>(seq_len_i64);

    hipError_t st = hipSetDevice(input_q.get_device());
    TORCH_CHECK(st == hipSuccess, "hipSetDevice failed: ", hipGetErrorString(st));

    auto out = torch::empty(
        {seq_len_i64, static_cast<int64_t>(MOE_HIDDEN_SIZE)},
        torch::TensorOptions().device(input_q.device()).dtype(torch::kBFloat16));

    const dim3 grid(static_cast<unsigned int>(seq_len), 1, 1);
    const dim3 block(static_cast<unsigned int>(MOE_THREADS), 1, 1);
    hipStream_t stream = nullptr;

    st = ksearch_launch_moe_fp8_blockscale_g1u1_topk4_e32_h7168_i2048_kernel(
        grid,
        block,
        0,
        stream,
        reinterpret_cast<const uint8_t*>(input_q.data_ptr()),
        reinterpret_cast<const uint8_t*>(w1_q.data_ptr()),
        reinterpret_cast<const uint8_t*>(w2_q.data_ptr()),
        topk_weights.data_ptr<float>(),
        topk_ids.data_ptr<int32_t>(),
        input_scale.data_ptr<float>(),
        fc1_scale.data_ptr<float>(),
        fc2_scale.data_ptr<float>(),
        reinterpret_cast<hip_bfloat16*>(out.data_ptr<c10::BFloat16>()),
        seq_len);

    TORCH_CHECK(st == hipSuccess, "Kernel launch failed: ", hipGetErrorString(st));

    if (return_cpu) {
        return out.cpu();
    }
    return out;
}

PYBIND11_MODULE(TORCH_EXTENSION_NAME, m) {
    m.def(
        "run",
        &run,
        py::arg("input_q"),
        py::arg("w1_q"),
        py::arg("w2_q"),
        py::arg("topk_weights"),
        py::arg("topk_ids"),
        py::arg("input_scale"),
        py::arg("fc1_scale"),
        py::arg("fc2_scale"));
}
